class Node {
public:
    ~Node() { std::cout << "Node destroyed\n"; }
    // std::shared_ptr<Node> next; // This would create a cycle
    std::weak_ptr<Node> prev; // Use weak_ptr to break the cycle
};

void create_cycle() {
    auto n1 = std::make_shared<Node>();
    auto n2 = std::make_shared<Node>();

    // n1 points to n2, n2 points back to n1
    // n1->next = n2; // If 'next' were shared_ptr, this would be a cycle
    n2->prev = n1; // n2 holds a non-owning pointer to n1

    // When n1 and n2 go out of scope, shared_ptr count for n1 goes to 0
    // and it is destroyed. Then n2 is destroyed.
}

// Checking a weak_ptr
auto sp = std::make_shared<int>(42);
std::weak_ptr<int> wp = sp;

if (auto locked_sp = wp.lock()) { // Must lock() to get a shared_ptr
    // Object still exists, we can use it
    std::cout << "Value: " << *locked_sp << std::endl;
} else {
    // Object has been destroyed
    std::cout << "Object is gone." << std::endl;
}

sp.reset(); // Destroy the object

if (wp.expired()) { // Check if the object is gone
    std::cout << "Object has expired." << std::endl;
}
